#!/usr/bin/env python3
"""Extracts the custom-provider identity policy from CustomProviderIdentity.kt."""
import sys

HEADER = """\
// GENERATED by extract_identity.py from CustomProviderIdentity.kt -- do not edit.
//
// The identity policy (id patterns, legacyId, isStableId, replaceStableIdsForDisplay, normalize,
// generateUniqueId and the remap helpers) is copied verbatim; only `private` is widened and the
// object members are lifted out of their 4-space indentation.
package com.newoether.agora.data

import java.util.Locale
import java.util.UUID
import java.nio.charset.StandardCharsets

"""

def extract_region(lines, marker, indent, widen):
    start = None
    for i, line in enumerate(lines):
        if line.startswith(marker):
            start = i
            break
    if start is None:
        raise SystemExit(f"error: {marker} not found")

    paren = 0
    brace = 0
    seen_brace = False
    end = None
    for i in range(start, len(lines)):
        for char in lines[i]:
            if char == "{":
                brace += 1
            elif char == "}":
                brace -= 1
            elif char in "([":
                paren += 1
            elif char in ")]":
                paren -= 1
        if brace > 0:
            if brace == 0:
                end = i
                break
            continue
        if brace < 0:
            raise SystemExit(f"error: negative brace count in {marker}")
        if paren != 0:
            continue
        stripped = lines[i].rstrip()
        if stripped.endswith(":"):
            continue
        if stripped.endswith(("=", ",", "&&", "||", "+", "->")):
            continue
        if i + 1 < len(lines):
            next_line = lines[i + 1].lstrip()
            if next_line.startswith(("?", "+", ".", "-", '"', "?", ":")):
                continue
            if next_line.startswith("        ") and not next_line.lstrip().startswith(("}", "fun", "val", "var", "const", "data", "class", "interface", "object", "sealed", "enum", "annotation", "typealias", "@")):
                continue
        end = i
        break
    if end is None:
        raise SystemExit(f"error: end of {marker} not found")

    prefix = " " * 4
    region = []
    for line in lines[start:end + 1]:
        if line.startswith("    "):
            line = line[4:]
        if widen:
            if line.startswith("private const val "):
                line = "internal const val " + line[len("private const val "):]
            elif line.startswith("private val "):
                line = "internal val " + line[len("private val "):]
            elif line.startswith("private fun "):
                line = "internal fun " + line[len("private fun "):]
            elif line.startswith("fun ") and not line.startswith("    "):
                line = "internal fun " + line[len("fun "):]
        region.append(line)
    return region


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: extract_identity.py <CustomProviderIdentity.kt> <out.kt>", file=sys.stderr)
        return 2

    lines = open(sys.argv[1], encoding="utf-8").read().split("\n")

    blocks = []
    for marker, indent, widen in [
        ("    private const val PREFIX =", 4, True),
        ("    private const val STABLE_ID_PATTERN =", 4, True),
        ("    private val stableIdPattern = Regex(", 4, True),
        ("    private val stableIdInTextPattern = Regex(", 4, True),
        ("    fun legacyId(name: String): String =", 4, True),
        ("    fun isStableId(value: String): Boolean = stableIdPattern.matches(value.trim())", 4, True),
        ("    fun replaceStableIdsForDisplay(", 4, True),
        ("    fun normalize(", 4, True),
        ("    private fun generateUniqueId(", 4, True),
        ("    fun newId(): String =", 4, True),
    ]:
        blocks.append("\n".join(extract_region(lines, marker, indent, widen)))

    top_blocks = []
    for marker in [
        "internal data class CustomProviderIdentityMigration(",
        "internal data class CustomProviderIdentityNormalization(",
        "internal fun String.remapProviderReference(",
        "internal fun <T> remapModelPreferenceKeys(",
        "internal fun canonicalCustomModelId(",
    ]:
        top_blocks.append("\n".join(extract_region(
            open(sys.argv[1], encoding="utf-8").read().split("\n"), marker, 0, False)))

    text = "internal object CustomProviderIdentityPolicy {\n" + "\n\n".join(blocks) + "\n}\n\n" + "\n\n".join(top_blocks)

    # Fix the normalize function's default parameter - rename parameter to avoid shadowing
    text = text.replace(
        "newId: (CustomProviderConfig) -> String = { newId() }",
        "idGenerator: (CustomProviderConfig) -> String = { newId() }"
    )
    # Update the call site in normalize
    text = text.replace(
        "generateUniqueId(raw, usedIds, newId)",
        "generateUniqueId(raw, usedIds, idGenerator)"
    )

    for name in ("normalize", "generateUniqueId", "legacyId", "isStableId",
                 "replaceStableIdsForDisplay", "CustomProviderIdentityNormalization",
                 "CustomProviderIdentityMigration", "remapProviderReference",
                 "remapModelPreferenceKeys", "canonicalCustomModelId", "PREFIX", "newId"):
        if name not in text:
            raise SystemExit(f"error: {name} missing from the extracted region")

    with open(sys.argv[2], "w", encoding="utf-8") as handle:
        handle.write(HEADER + text + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())


HEADER = """\
// GENERATED by extract_identity.py from CustomProviderIdentity.kt -- do not edit.
//
// The identity policy (id patterns, legacyId, isStableId, replaceStableIdsForDisplay, normalize,
// generateUniqueId and the remap helpers) is copied verbatim; only `private` is widened and the
// object members are lifted out of their 4-space indentation.
package com.newoether.agora.data

import java.util.Locale
import java.util.UUID
import java.nio.charset.StandardCharsets

"""